unsafe fn readBitsFromReversedStream(
    mut bitpointer: *mut size_t,
    mut bitstream: *const c_uchar,
    mut nbits: size_t,
) -> c_uint {
    let mut result: c_uint = 0;
    if nbits == 0 {
        return 0;
    }

    // SAFETY: `bitpointer` is assumed valid by the original function contract; we only read and
    // write the pointed value, and `bitstream` is assumed valid for the bytes touched by the bit range.
    let mut bp = unsafe { *bitpointer };
    let start_byte = bp >> 3;
    let start_bit = bp & 7;

    let mut remaining = nbits;
    let mut p = bitstream.wrapping_add(start_byte);
    let mut bit = start_bit;

    while remaining != 0 {
        // SAFETY: `p` points into the caller-provided bitstream at the current byte containing the
        // next requested bit; dereferencing matches the access pattern of the original loop.
        let byte = unsafe { *p } as c_uint;
        let take = core::cmp::min(remaining, bit + 1);
        let shift = bit + 1 - take;
        let mask = ((1usize << take) - 1) as c_uint;
        let chunk = (byte >> shift) & mask;

        result = (result << take) | chunk;
        remaining -= take;

        if shift == 0 {
            p = p.wrapping_add(1);
            bit = 7;
        } else {
            bit = shift - 1;
        }
    }

    bp = bp.wrapping_add(nbits);
    // SAFETY: `bitpointer` is assumed valid by the original function contract; we store back the
    // updated bit position exactly as the original function would after `nbits` single-bit reads.
    unsafe {
        *bitpointer = bp;
    }
    result
}

